int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int E, M, D;
    cin >> E >> M >> D;

    vector<pair<int, int>> want(M), avoid(D);

    for (auto &[x, y] : want) cin >> x >> y;
    for (auto &[u, v] : avoid) cin >> u >> v;

    vector<int> group(E + 1);
    for (int g = 0; g < E / 3; ++g) {
        int i, j, k;
        cin >> i >> j >> k;
        group[i] = group[j] = group[k] = g;
    }

    int violated = 0;

    for (auto [x, y] : want)
        if (group[x] != group[y]) ++violated;

    for (auto [u, v] : avoid)
        if (group[u] == group[v]) ++violated;

    cout << violated << '\n';
    return 0;
}
